struct Hinoko {
    unsigned char active;
    Vec3f pos[2];
    Vec3f dir[2];
    clNormal3D *model;
    HSD_JObj *joints[3];
    Ember embers[20];
    int cooldown;
    int rnd;

    Hinoko();
    ~Hinoko() {
        if (model) {
            delete model;
            model = 0;
        }
    }
    void SetPos(const Vec3f *p) {
        pos[0].x = p[0].x;
        pos[0].y = p[0].y;
        pos[0].z = p[0].z;
        pos[1].x = p[1].x;
        pos[1].y = p[1].y;
        pos[1].z = p[1].z;
    }
    void SetDir(const Vec3f *d) {
        dir[0].x = d[0].x;
        dir[0].y = d[0].y;
        dir[0].z = d[0].z;
        dir[1].x = d[1].x;
        dir[1].y = d[1].y;
        dir[1].z = d[1].z;
    }
    float Rand() {
        if (++rnd >= 64) {
            rnd = 0;
        }
        return lbl_80495994[rnd];
    }
    void Spawn();
    void Update();
};

struct clMapEffectParts {
    virtual ~clMapEffectParts() {}
    virtual void Update();
    virtual void Draw();
    virtual void Enable(int on);
    clMapEffectParts() {}
};

struct clDNStartDino : clMapEffectParts {
    clNormal3D *gate;
    GateAnim *anim;
    clNormal3D *unused;
    clNormal3D *fire;
    HSD_JObj *fireL;
    HSD_JObj *fireR;
    float f1C;
    Vec3f firePos[2];
    Vec3f fireDir[2];
    int rnd;
    unsigned char fireOn;
    int cooldown;
    unsigned char hideGate;
    unsigned char hideFire;
    int timer;
    FirePuff puffs[20];
    FirePuff *freePuffs[2];
    Hinoko *hinoko;
    int jointSet;
    unsigned char challenge;

    clDNStartDino(HSD_JObj *at);
    virtual void Enable(int on);
    virtual ~clDNStartDino();
    virtual void Update();
    virtual void Draw();
    void SpawnFire();
    void Animate() {
        if (challenge == 1) {
            clNormal3D_Exec(gate);
        } else {
            anim->Update();
        }
        Object_DriveAnimMatrix(gate);
    }
};

