void clDNStartDino::Draw() {
    Mtx m;
    Hinoko *h;
    int c;
    int i;

    if (hideGate == 1) {
        return;
    }
    if (gate) {
        Object_RenderJObjTree(gate, 7);
    }
    if (hideFire == 1) {
        return;
    }
    if (fire) {
        GXChannel ch(Archive_GetRootJObj(fire), HSD_JObjGetDObj(Archive_GetRootJObj(fire)), 0x40000000, 1);
        for (i = 0; i < 20; i++) {
            if (puffs[i].active) {
                PSMTXScale(m, puffs[i].scale, puffs[i].scale, puffs[i].scale);
                m[0][3] = puffs[i].pos.x;
                m[1][3] = puffs[i].pos.y;
                m[2][3] = puffs[i].pos.z;
                Object_SetColorAlphaOnly(fire, 0, puffs[i].alpha);
                ch.PushTransform(m);
            }
        }
    }
    h = hinoko;
    if (h->model && h->joints[0] && h->joints[1] && h->joints[2] && fn_801379F0(h->pos, lbl_806DB540)) {
        for (c = 0; c < 3; c++) {
            Mtx em;
            GXChannel ch(h->joints[c], HSD_JObjGetDObj(h->joints[c]), 0x40000000, 1);
            for (i = 0; i < 20; i++) {
                if (h->embers[i].active && h->embers[i].color == c) {
                    PSMTXScale(em, h->embers[i].scale, h->embers[i].scale, h->embers[i].scale);
                    em[0][3] = h->embers[i].pos.x;
                    em[1][3] = h->embers[i].pos.y;
                    em[2][3] = h->embers[i].pos.z;
                    Object_SetColorAlphaOnly(h->model, 0, h->embers[i].alpha);
                    ch.PushTransform(em);
                }
            }
        }
    }
}

void clDNStartDino::SpawnFire() {
    for (int i = 0; i < 2; i++) {
        FirePuff *p = freePuffs[i];
        if (p) {
            float n = lbl_806DB54C * (lbl_80495A94[rnd] - lbl_806DB508);
            p->vel.x = fireDir[i].x;
            p->vel.y = fireDir[i].y;
            p->vel.z = fireDir[i].z + n;
            p->pos.x = firePos[i].x;
            p->pos.y = firePos[i].y;
            p->pos.z = firePos[i].z;
            p->scale = lbl_806DB550;
            p->alpha = lbl_806DB534;
            p->lift = lbl_806DB530 * n;
            if (n < lbl_806DB524) {
                n = -n;
            }
            n = n / lbl_806DB54C;
            float s = lbl_806DB534 - n;
            if (lbl_80495A94[rnd] >= lbl_806DB558) {
                s = lbl_806DB554;
            }
            p->speed = lbl_806DB560 * s + lbl_806DB55C;
            p->dscale = lbl_806DB568 * n + lbl_806DB564;
            p->fade = lbl_806DB570 * n + lbl_806DB56C;
            p->active = 1;
            freePuffs[i] = 0;
        }
    }
    cooldown = 5;
    if (++rnd >= 48) {
        rnd = 0;
    }
}

void clDNStartDino::Update() {
    Vec3f local;
    Vec3f eye9;
    Vec3f eye;
    if (gate == 0 || fire == 0) {
        return;
    }
    {
    if (!IsRaceStarted()) {
        hideGate = 0;
        hideFire = 1;
        Animate();
        return;
    }
    hideFire = 1;
    hideGate = 1;
    if (g_cupId >= 9) {
        CObj_LoadProjMatrix(GetCourseScene3D(), &eye9);
        float z = eye9.z;
        hideGate = 0;
        hideFire = 0;
        if (z >= lbl_806DB544) {
            if (jointSet != 0) {
                fireL = ResolveJointByName(gate, lbl_803DA1B0);
                fireR = ResolveJointByName(gate, lbl_803DA1C4);
            }
        } else if (jointSet != 1) {
            fireL = ResolveJointByName(gate, lbl_803DA1D8);
            fireR = ResolveJointByName(gate, lbl_803DA1EC);
        }
    } else {
        CObj_LoadProjMatrix(GetCourseScene3D(), &eye);
        if (eye.x >= lbl_803DA13C[0] && eye.x <= lbl_803DA13C[2]) {
            if (eye.z >= lbl_803DA13C[1] && eye.z <= lbl_803DA13C[3]) {
                hideFire = 0;
            }
            if (eye.z >= lbl_803DA12C[1] && eye.z <= lbl_803DA12C[3]) {
                hideGate = 0;
            }
        }
    }
    if (g_gameMode == 2) {
        Animate();
        return;
    }
    if (hideFire == 0) {
        if (fireOn == 0) {
            fireOn = 1;
            hinoko->active = 1;
        }
    } else if (fireOn != 0) {
        fn_8016C394(0x34);
        fireOn = 0;
        hinoko->active = 0;
    }
    if (timer < 0) {
        fn_8016C394(0x34);
        fireOn = 0;
        hinoko->active = 0;
    }
    if (fireOn == 1) {
        local.x = lbl_806D05D0;
        local.y = lbl_806D05D4;
        local.z = lbl_806D05D8;
        float (*mm)[4] = JObjGetMtx(fireL);
        PSMTXMultVecSR(mm, &local, &fireDir[0]);
        firePos[0].x = mm[0][3];
        firePos[0].y = mm[1][3];
        firePos[0].z = mm[2][3];
        mm = JObjGetMtx(fireR);
        PSMTXMultVecSR(mm, &local, &fireDir[1]);
        firePos[1].x = mm[0][3];
        firePos[1].y = mm[1][3];
        firePos[1].z = mm[2][3];
        fn_8016C288(0x34, firePos);
        hinoko->SetPos(firePos);
        hinoko->SetDir(fireDir);
    }
    int nfree = 0;
    for (int i = 0; i < 20; i++) {
        if (!puffs[i].active) {
            if (nfree < 2) {
                freePuffs[nfree++] = &puffs[i];
            }
        } else {
            FirePuff *p = &puffs[i];
            p->pos.x = p->vel.x * p->speed + p->pos.x;
            p->pos.y = p->vel.y * p->speed + p->pos.y;
            p->pos.z = p->vel.z * p->speed + p->pos.z;
            p->scale += p->dscale;
            p->vel.y += p->lift;
            p->speed -= lbl_806DB514;
            p->alpha -= p->fade;
            p->dscale *= lbl_806DB548;
            if (p->alpha <= lbl_806DB524) {
                p->active = 0;
            }
        }
    }
    if (hideFire == 0) {
        if (cooldown == 0 && fireOn == 1) {
            SpawnFire();
        }
        if (++timer > 180) {
            f1C = lbl_806DB524;
            timer = -125;
        }
        Animate();
    } else {
        if (timer < 0) {
            timer++;
        }
        if (timer > 0) {
            if (++timer > 180) {
                timer = 0;
            }
        }
    }
    if (cooldown != 0) {
        cooldown--;
    }
    hinoko->Update();
    }
}
